"""Curie-Weiss magnetization: solve m = tanh(beta*m) and trace the bifurcation."""
from __future__ import annotations
import math

def magnetization(beta: float, tol: float = 1e-14) -> float:
    """Positive magnetization m solving m = tanh(beta*m); 0 for beta <= 1."""
    if beta <= 1.0:
        return 0.0
    lo, hi = tol, 1.0
    f = lambda x: math.tanh(beta * x) - x
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if f(mid) > 0.0:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)

if __name__ == "__main__":
    for beta in [0.5, 0.99, 1.0, 1.01, 1.2, 1.5, 2.0, 4.0]:
        m = magnetization(beta)
        bound = math.sqrt(3*(beta-1)/beta**3) if beta > 1 else 0.0
        print(f"beta={beta:5.2f}  m={m:.6f}  sqrt-bound={bound:.6f}")

"""Mean-field percolation: solve rho = 1 - exp(-lam*rho) for the giant-component fraction."""
from __future__ import annotations
import math

def survival_probability(lam: float, tol: float = 1e-14) -> float:
    """Giant-component fraction rho solving rho = 1 - exp(-lam*rho); 0 for lam <= 1."""
    if lam <= 1.0:
        return 0.0
    lo, hi = tol, 1.0
    f = lambda x: -math.expm1(-lam * x) - x  # -expm1 avoids cancellation
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if f(mid) > 0.0:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)

if __name__ == "__main__":
    for lam in [0.5, 0.99, 1.0, 1.01, 1.2, 1.5, 2.0, 4.0]:
        rho = survival_probability(lam)
        bound = 2*(lam-1)/lam**2 if lam > 1 else 0.0
        print(f"lam={lam:5.2f}  rho={rho:.6f}  linear-bound={bound:.6f}")

