from __future__ import annotations
from typing import Callable, Optional

def solve_positive_fixed_point(
    phi: Callable[[float], float],
    upper: float = 1.0,
    tol: float = 1e-14,
    max_iter: int = 300,
) -> Optional[float]:
    """Largest x in (0, upper] with phi(x) = x, via bisection on F(x)=phi(x)-x.

    Requires F(0+) > 0 and F(upper) < 0 (the supercritical sign pattern of both
    mean-field models). Returns None if no bracketed root exists.
    """
    f = lambda x: phi(x) - x
    lo, hi = tol, upper
    if f(lo) <= 0.0 or f(hi) >= 0.0:
        return None
    for _ in range(max_iter):
        mid = 0.5 * (lo + hi)
        if f(mid) > 0.0:
            lo = mid
        else:
            hi = mid
        if hi - lo < tol:
            break
    return 0.5 * (lo + hi)
